const rows = $input.all().map(item => {
const cleaned = {};

for (const [key, value] of Object.entries(item.json)) {
  const cleanKey = key.replace(/^\uFEFF/, "").trim();
  cleaned[cleanKey] = value;
}

return {
  ...item,
  json: cleaned
};
});


const requiredColumns = [
  "event_id",
  "lead_id",
  "name",
  "email",
  "service"
];

const fields = [
  "event_id",
  "lead_id",
  "name",
  "email",
  "phone",
  "company",
  "service",
  "budget",
  "timeline",
  "message",
  "source"
];

if (rows.length === 0) {
  throw new Error("The CSV contains no records.");
}

if (rows.length > 100) {
  throw new Error(
    "Maximum 100 records per import for this test."
  );
}

const firstRow = rows[0].json;

const missing = requiredColumns.filter(
  column => !(column in firstRow)
);

if (missing.length > 0) {
  throw new Error(
    "Missing CSV columns: " + missing.join(", ")
  );
}

const eventIds = new Set();

return rows.map((item, index) => {
  const row = item.json;
  const lead = {};

  for (const field of fields) {
    lead[field] =
      String(row[field] ?? "").trim();
  }

  if (!lead.source) {
    lead.source = "csv_import";
  }

  if (lead.event_id) {
    if (eventIds.has(lead.event_id)) {
      throw new Error(
        `Duplicate event_id at CSV row ${index + 2}`
      );
    }

    eventIds.add(lead.event_id);
  }

  return {
    json: {
      ...lead,
      csv_row_number: index + 2
    },
    pairedItem: {
      item: index
    }
  };
});

const responses = $input.all();

return responses.map((item, index) => {
  const data = item.json;

  const status = Number(
    data.statusCode ?? 0
  );

  const body =
    data.body && typeof data.body === "object"
      ? data.body
      : {};

  let outcome = "failed";

  if (status === 200) {
    outcome = body.duplicate
      ? "duplicate"
      : "successful";
  } else if (status === 400) {
    outcome = "rejected";
  } else if (status === 409) {
    outcome = "in_progress";
  }

  return {
    json: {
      event_id: body.event_id ?? null,
      lead_id: body.lead_id ?? null,
      email: body.email ?? null,
      http_status: status,
      outcome,
      response: body,
      transport_error:
        data.error?.message ??
        (status === 0
          ? data.message ?? null
          : null)
    },
    pairedItem: {
      item: index
    }
  };
});

const records = $input.all().map(
  item => item.json
);

const summary = {
  total: records.length,
  successful: 0,
  duplicate: 0,
  rejected: 0,
  in_progress: 0,
  failed: 0
};

for (const record of records) {
  if (record.outcome in summary) {
    summary[record.outcome]++;
  } else {
    summary.failed++;
  }
}

return [{
  json: {
    import_status:
      summary.failed === 0 &&
      summary.in_progress === 0
        ? "finished"
        : "requires_attention",

    summary,

    records,

    completed_at: new Date().toISOString()
  }
}];
